import React,{useState} from 'react';import{createRoot}from'react-dom/client';import SearchableSelect from '/src/components/SearchableSelect.jsx';import '/src/style.css';
function App(){const[value,set]=useState('');const [saved,save]=useState(false);return <form onSubmit={e=>{e.preventDefault();save(true)}}><label className="field">Jugador<SearchableSelect aria-label="Jugador" required value={value} onChange={e=>set(e.target.value)}><option value="">Seleccionar</option><option value="1">Egor Dëmin</option><option value="2">José Alvarado</option>{Array.from({length:519},(_,i)=><option key={i} value={'p'+i}>Jugador {i}</option>)}</SearchableSelect></label><button>Guardar</button><output>{value}|{String(saved)}</output></form>}createRoot(document.getElementById('root')).render(<App/>);
